import subprocess
def run(inp):
    if isinstance(inp,str): inp=inp.encode()
    p=subprocess.run(['./executable'], input=inp, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return p.stdout
def pretty(out):
    return out.replace(b'\x1b', b'<ESC>').decode('utf-8', errors='replace')
def t(inp):
    out=run(inp)
    print(f"IN={inp!r}")
    print(pretty(out))
    print()

# continuation chars: after @@, which first chars keep hunk alive?
for ch in [" ", "-", "+", "\\", "@", "", "\t", "*", "#", "d", "i", "X", "!", "?", ">", "<", ":", ";", ".", "a"]:
    if ch == "":
        inp = b"@@ -1 +1 @@\n\n-foo\n"
    else:
        inp = (b"@@ -1 +1 @@\n" + ch.encode() + b"foo\n-foo\n")
    out=run(inp)
    p=pretty(out)
    # check if last -foo is colored (contains 31m-)
    colored = "<ESC>[31m-" in p.split("\n")[-2] if len(p.split("\n"))>=2 else False
    # Actually need to check last line
    print(f"ch={ch!r} colored={colored} out={p!r}")

PY
"}

