def process_stream(data_bytes, faces, line_style):
    if len(data_bytes) == 0:
        return (b"", 0)
    has_trailing_nl = data_bytes.endswith(b'\n')
    parts = data_bytes.split(b'\n')
    lines = []
    if has_trailing_nl:
        for p in parts[:-1]:
            lines.append((p, True))
    else:
        for p in parts[:-1]:
            lines.append((p, True))
        lines.append((parts[-1], False))
    decoded = []
    for bline, has_nl in lines:
        s = bline.decode('utf-8', errors='surrogateescape')
        decoded.append((s, has_nl))
    out_parts = []
    in_hunk = False
    hunk_buffer = []
    for s, has_nl in decoded:
        is_at = s.startswith("@") and len(s) > 0
        is_cont = False
        if in_hunk and len(s) > 0 and s[0] in (' ', '-', '+', '\\'):
            is_cont = True
        elif in_hunk and s == "":
            # empty line (from "\n" with no content) -> breaks (since "" doesn't start with those)
            is_cont = False
        if is_at:
            if in_hunk:
                rc = flush_hunk(hunk_buffer, faces, line_style, out_parts)
                if rc != 0:
                    # io error: need to output up to before failing? flush_hunk already appended header etc. up to failing point? Actually it appended header and prior \\, but not failing line. Good.
                    # Encode out_parts and return with error
                    out_str = "".join(out_parts)
                    out_bytes = out_str.encode('utf-8', errors='surrogateescape')
                    return (out_bytes, 1)
                hunk_buffer = []
            in_hunk = True
            hunk_buffer.append((s, has_nl))
        elif in_hunk and is_cont:
            # Special: "@" lines inside hunk? Actually is_at already handled (starts new hunk). So here is_cont for ' ', '-', '+', '\\' only.
            # But what about "@" line that is_cont? No, "@" already handled as new hunk, not cont. Good.
            hunk_buffer.append((s, has_nl))
        else:
            if in_hunk:
                rc = flush_hunk(hunk_buffer, faces, line_style, out_parts)
                if rc != 0:
                    out_str = "".join(out_parts)
                    out_bytes = out_str.encode('utf-8', errors='surrogateescape')
                    return (out_bytes, 1)
                hunk_buffer = []
                in_hunk = False
            # plain line
            out_parts.append(RESET)
            out_parts.append(s)
            out_parts.append(RESET)
            if has_nl:
                out_parts.append("\n")
    if in_hunk:
        rc = flush_hunk(hunk_buffer, faces, line_style, out_parts)
        if rc != 0:
            out_str = "".join(out_parts)
            out_bytes = out_str.encode('utf-8', errors='surrogateescape')
            return (out_bytes, 1)
    out_str = "".join(out_parts)
    out_bytes = out_str.encode('utf-8', errors='surrogateescape')
    return (out_bytes, 0)

def main():
    argv = sys.argv[1:]
    faces, line_style, exit_code, out_data, err_data = parse_cli(argv)
    if exit_code is not None:
        if out_data:
            sys.stdout.write(out_data)
        if err_data:
            sys.stderr.write(err_data)
        sys.exit(exit_code)
    data = sys.stdin.buffer.read()
    out_bytes, rc = process_stream(data, faces, line_style)
    if rc != 0:
        # io error
        try:
            sys.stdout.buffer.write(out_bytes)
            sys.stdout.buffer.flush()
        except:
            pass
        sys.stderr.write("io error: failed to write whole buffer\n")
        sys.exit(255)
    try:
        sys.stdout.buffer.write(out_bytes)
    except BrokenPipeError:
        sys.stderr.write("io error: failed to write whole buffer\n")
        sys.exit(255)

if __name__ == "__main__":
    main()
