    p=subprocess.run(['./executable'], input=inp, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return p.stdout
def pretty(out):
    return out.replace(b'\x1b', b'<ESC>').decode()
def t(inp):
    out=run(inp)
    print(f"IN={inp!r}")
    print(pretty(out))
    print()

t(b"@@ -1,2 +1,2 @@\n-foo\n-bar\n+baz\n+qux\n")
t(b"@@ -1,3 +1,3 @@\n-foo\n-bar\n-baz\n+qux\n+quux\n+quuz\n")
PY
"}

